import kotlinx.coroutines.ensureActive

suspend fun recoverOrPropagate(): Int {
    try {
        delay(1L)
        return 7
    } catch (failure: Exception) {
        if (failure !is CancellationException) currentCoroutineContext().ensureActive()
        return 0
    }
}

